package com.lmspilot.organization.api;import com.lmspilot.support.security.InternalTokenAuthorizer;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/organization") public class InternalOrganizationScopeController{private final OrganizationMembershipService service;private final InternalTokenAuthorizer internal;public InternalOrganizationScopeController(OrganizationMembershipService s,InternalTokenAuthorizer i){service=s;internal=i;}@GetMapping("/units/{id}/descendants") public Set<UUID> descendants(@PathVariable UUID id,@RequestHeader(value="X-Service-Token",required=false)String token){internal.require(token);return service.descendants(id);}@GetMapping("/users/{userId}/unit-ids") public Set<UUID> userUnitIds(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String token){internal.require(token);Set<UUID> out=new HashSet<>();for(var r:service.byUser(userId))if(r.active())out.add(r.unitId());return out;}@GetMapping("/units/{id}/users") public Set<UUID> users(@PathVariable UUID id,@RequestHeader(value="X-Service-Token",required=false)String token){internal.require(token);return service.usersInScope(id);}@GetMapping("/units/{id}/ancestors") public Set<UUID> ancestors(@PathVariable UUID id,@RequestHeader(value="X-Service-Token",required=false)String token){internal.require(token);return service.ancestors(id);}}
